# One application object (home tenant), one service principal per tenant using it.
app = {"appId": "hr-app", "home": "adatum", "credentials": ["cert-2026"]}
service_principals = {
    "adatum":   {"granted": ["User.Read"]},
    "contoso":  {"granted": ["User.Read.All (application)"]},
    "fabrikam": {"granted": ["Mail.Read (delegated)"]},
}

def token_for(tenant, credential):
    # The app proves itself with a credential on the APPLICATION object;
    # what it may do comes from the SERVICE PRINCIPAL in the target tenant.
    if credential not in app["credentials"]:
        return f"{tenant}: rejected, unknown credential"
    sp = service_principals.get(tenant)
    if sp is None:
        return f"{tenant}: no service principal, nothing consented"
    return f"{tenant}: token with {sp['granted']}"

for t in ["contoso", "fabrikam", "northwind"]:
    print(token_for(t, "cert-2026"))

# Someone who controls the home tenant's app object adds a credential:
app["credentials"].append("secret-added-by-owner")
print(token_for("contoso", "secret-added-by-owner"))

# Output:
# contoso: token with ['User.Read.All (application)']
# fabrikam: token with ['Mail.Read (delegated)']
# northwind: no service principal, nothing consented
# contoso: token with ['User.Read.All (application)']

MAILBOXES = ["ana", "raj", "ceo", "cfo"]
USER_CAN_READ = {"ana": {"ana"}, "raj": {"raj", "ceo"}}   # raj is the CEO's delegate

def readable(permission, kind, user=None):
    if permission != "Mail.Read":
        return set()
    if kind == "delegated":
        # app AND user must both be allowed: the intersection
        return USER_CAN_READ.get(user, set()) & set(MAILBOXES)
    if kind == "application":
        # no user in the picture: every mailbox the permission covers
        return set(MAILBOXES)

print("delegated, signed in as ana:", sorted(readable("Mail.Read", "delegated", "ana")))
print("delegated, signed in as raj:", sorted(readable("Mail.Read", "delegated", "raj")))
print("application permission:     ", sorted(readable("Mail.Read", "application")))

# Entra audit rows (simplified). Pattern from Octo Tempest / Scattered Spider:
# help desk resets an admin, a new MFA method appears, then a domain is federated.
audit = [
  {"min": 0,  "activity": "Reset password (by admin)", "by": "helpdesk-07", "target": "it-admin-2"},
  {"min": 4,  "activity": "Admin deleted security info", "by": "helpdesk-07", "target": "it-admin-2"},
  {"min": 9,  "activity": "User registered security info", "by": "it-admin-2", "target": "it-admin-2"},
  {"min": 31, "activity": "Set domain authentication", "by": "it-admin-2", "target": "corp-sso.example"},
]
PRIVILEGED = {"it-admin-2"}
RISKY = {"Set domain authentication", "Set federation settings on domain"}

reset_at = {}
for e in audit:
    if e["target"] in PRIVILEGED and e["by"].startswith("helpdesk"):
        reset_at[e["target"]] = e["min"]
        print(f"t+{e['min']:>2}: {e['activity']} on privileged {e['target']} by {e['by']}")
    elif e["activity"] == "User registered security info" and e["by"] in reset_at:
        print(f"t+{e['min']:>2}: new MFA method {e['min'] - reset_at[e['by']]} min after a help desk reset")
    elif e["activity"] in RISKY:
        print(f"t+{e['min']:>2}: ALERT {e['activity']} by {e['by']} on {e['target']}")

# Output:
# t+ 0: Reset password (by admin) on privileged it-admin-2 by helpdesk-07
# t+ 4: Admin deleted security info on privileged it-admin-2 by helpdesk-07
# t+ 9: new MFA method 5 min after a help desk reset
# t+31: ALERT Set domain authentication by it-admin-2 on corp-sso.example
